+    private readonly List<Notification> _notifications = [];
+
+    public NotificationService()
+    {
+        // Seed with initial fake data
+        _notifications.AddRange(
+        [
+            new(NextId(), "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)),
+            new(NextId(), "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)),
+            new(NextId(), "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)),
+        ]);
+    }
+
+    public Task<List<Notification>> GetNotificationsAsync()
+    {
+        lock (_notifications)
+        {
+            return Task.FromResult(_notifications.ToList());
+        }
+    }
+
+    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
+    {
+        lock (_notifications)
+        {
+            var newer = _notifications.Where(n => n.Id > lastId).ToList();
+            return Task.FromResult(newer);
+        }
+    }
+
+    /// <summary>
+    /// Simulates new notifications arriving over time.
+    /// Called internally by the polling loop to generate fake data.
+    /// </summary>
+    public Task SimulateIncomingAsync()
+    {
+        if (Random.Shared.NextDouble() < 0.3) // 30% chance each poll
+        {
