+                "Someone commented on your post.",
+                "Your build succeeded.",
+                "Reminder: meeting in 15 minutes.",
+                "New deployment completed.",
+            };
+
+            lock (_notifications)
+            {
+                _notifications.Add(new(
+                    NextId(),
+                    messages[Random.Shared.Next(messages.Length)],
+                    DateTime.UtcNow));
+            }
+        }
